#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long maxProduct(vector<int>& nums, int target) {
        int n = nums.size();
        long long best = -4e18;
        for (int i = 0; i < n; ++i) {
            vector<long long> cand;
            for (int j = 0; j < n; ++j) {
                cand.push_back(i == j ? target : nums[j]);
            }
            sort(cand.begin(), cand.end());
            long long p1 = cand[n - 1] * cand[n - 2] * cand[n - 3];
            long long p2 = cand[0] * cand[1] * cand[n - 1];
            best = max({best, p1, p2});
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public long maxProduct(int[] nums, int target) {
        int n = nums.length;
        long best = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            long[] cand = new long[n];
            for (int j = 0; j < n; j++) {
                cand[j] = (i == j) ? target : nums[j];
            }
            Arrays.sort(cand);
            long p1 = cand[n - 1] * cand[n - 2] * cand[n - 3];
            long p2 = cand[0] * cand[1] * cand[n - 1];
            best = Math.max(best, Math.max(p1, p2));
        }
        return best;
    }
}

var maxProduct = function(nums, target) {
    const n = nums.length;
    let best = null;
    for (let i = 0; i < n; i++) {
        const cand = [];
        for (let j = 0; j < n; j++) {
            cand.push(BigInt(i === j ? target : nums[j]));
        }
        cand.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
        const p1 = cand[n - 1] * cand[n - 2] * cand[n - 3];
        const p2 = cand[0] * cand[1] * cand[n - 1];
        const curBest = p1 > p2 ? p1 : p2;
        if (best === null || curBest > best) {
            best = curBest;
        }
    }
    return Number(best);
};
